import saviors from "../data/saviors.json";

let ranks = null;

const STAT_TYPE = {
    NST_ATK: "atk",
    NST_HP: "hp",
    NST_DEF: "def",
    NST_TURN_SPEED: "spd",
    NST_NV_RATE_ATK: "atk_rate",
    NST_NV_RATE_HP: "hp_rate",
    NST_NV_RATE_DEF: "def_rate",
    NST_RATE_CRITICAL: "crit_rate",
    NST_RATE_CRITICAL_DAMAGE: "crit_dmg",
    NST_RATE_EFFECT_HIT: "eff_rate",
    NST_RATE_EFFECT_EVADE: "eff_resist",
};

const addTotalResonance = (leveledStats, resonances) => {
    const obj = {};

    for (const resonance of resonances) {
        const stats = resonance.stats;

        if (stats) {
            for (const stat of stats) {
                if (obj[stat.type]) obj[stat.type] += stat.value;
                else obj[stat.type] = stat.value;
            }
        }
    }

    leveledStats[STAT_TYPE.NST_ATK] += obj[STAT_TYPE.NST_ATK] || 0;
    leveledStats[STAT_TYPE.NST_HP] += obj[STAT_TYPE.NST_HP] || 0;
    leveledStats[STAT_TYPE.NST_DEF] += obj[STAT_TYPE.NST_DEF] || 0;
    leveledStats[STAT_TYPE.NST_TURN_SPEED] += obj[STAT_TYPE.NST_TURN_SPEED] || 0;
    leveledStats[STAT_TYPE.NST_RATE_CRITICAL] =
        (leveledStats[STAT_TYPE.NST_RATE_CRITICAL] * 10_000 + (obj[STAT_TYPE.NST_RATE_CRITICAL] || 0) * 10_000) / 10_000;
    leveledStats[STAT_TYPE.NST_RATE_CRITICAL_DAMAGE] =
        (leveledStats[STAT_TYPE.NST_RATE_CRITICAL_DAMAGE] * 10_000 + (obj[STAT_TYPE.NST_RATE_CRITICAL_DAMAGE] || 0) * 10_000) / 10_000;
    leveledStats[STAT_TYPE.NST_RATE_EFFECT_HIT] += obj[STAT_TYPE.NST_RATE_EFFECT_HIT] || 0;
    leveledStats[STAT_TYPE.NST_RATE_EFFECT_EVADE] += obj[STAT_TYPE.NST_RATE_EFFECT_EVADE] || 0;

    leveledStats[STAT_TYPE.NST_ATK] = Math.floor(leveledStats[STAT_TYPE.NST_ATK] * (1 + (obj[STAT_TYPE.NST_NV_RATE_ATK] || 0)));
    leveledStats[STAT_TYPE.NST_HP] = Math.floor(leveledStats[STAT_TYPE.NST_HP] * (1 + (obj[STAT_TYPE.NST_NV_RATE_HP] || 0)));
    leveledStats[STAT_TYPE.NST_DEF] = Math.floor(leveledStats[STAT_TYPE.NST_DEF] * (1 + (obj[STAT_TYPE.NST_NV_RATE_DEF] || 0)));
};

const addTotalFavorStats = (totalStats, faverLevelInfos) => {
    for (const favorLevelInfo of faverLevelInfos) {
        if (favorLevelInfo.stats.length > 0) {
            totalStats.atk += favorLevelInfo.stats.find((e) => e.type === STAT_TYPE.NST_ATK).value;
            totalStats.hp += favorLevelInfo.stats.find((e) => e.type === STAT_TYPE.NST_HP).value;
            totalStats.def += favorLevelInfo.stats.find((e) => e.type === STAT_TYPE.NST_DEF).value;
        }
    }
};

const construct = () => {
    if (!ranks) {
        ranks = saviors.map((e) => {
            const status = e.base_stat;

            for (let i = 1; i < 200; i++) {
                status.atk += e.stat_per_level.atk;
                status.hp += e.stat_per_level.hp;
                status.def += e.stat_per_level.def;
            }

            addTotalResonance(status, e.resonances);
            addTotalFavorStats(status, e.favor_per_level);

            return {
                id: e.id,
                name: e.name,
                title: e.title,
                status: status,
            };
        });
        const keys = ["atk", "hp", "def", "spd", "crit_rate", "crit_dmg"];

        keys.forEach((key) => {
            const sorted = [...ranks].sort((a, b) => (b.status[key] || 0) - (a.status[key] || 0));

            for (let i = 0; i < sorted.length; i++) {
                const s = sorted[i];
                s.ranks = s.ranks || {};

                if (i > 0 && (sorted[i].status[key] || 0) === (sorted[i - 1].status[key] || 0)) {
                    s.ranks[key] = sorted[i - 1].ranks[key];
                } else {
                    s.ranks[key] = i + 1;
                }
            }
        });
    }

    return ranks;
};

construct();

const getSaviorStatRanks = () => ranks;
const getSaviorStatRankById = (id) => ranks.find((e) => e.id === id);

export { getSaviorStatRanks, getSaviorStatRankById };
