import { createSlice } from "@reduxjs/toolkit";
import originData from "../../../data/arcanas.json";
import FILTERS from "../../../data/filter_config.json";
import potentials from "../../../data/potentials.json";
import buffs from "../../../data/journey_buffs.json";

const STATUS_BASIC_SCORE = {
    힘: 1,
    체력: 2,
    인내: 3,
    집중: 4,
    보호: 5,
};

const RARITY_BASIC_SCORE = {
    R: 0,
    SR: 1,
    SSR: 2,
};

const getTypeString = (stat, mainStat) => {
    if (stat.value_type === "{stat}") return mainStat;
    else if (stat.value_type.includes("{stat}")) return stat.value_type.replaceAll("{stat}", mainStat);

    return stat.value_type;
};

const calcValueByLevel = (stat, targetLevel, isRate) => {
    const count = Math.floor((targetLevel - stat.unlock_level) / stat.promote_per_level);
    if (count < 0) return 0;

    const base = isRate ? stat.value_rate : stat.value_int;
    const promoteValue = isRate ? stat.value_rate_per_promote : stat.value_int_per_promote;

    return base + count * promoteValue;
};

const getValuesSepLevel = (stat) => {
    const isRate = stat.value_rate !== 0 ? true : false;
    const values = { level_35: 0, level_50: 0, isRate };

    values.level_35 = calcValueByLevel(stat, 35, isRate);
    values.level_35_string = isRate ? `${(values.level_35 / 100).toFixed(2)}%` : values.level_35;
    values.level_50 = calcValueByLevel(stat, 50, isRate);
    values.level_50_string = isRate ? `${(values.level_50 / 100).toFixed(2)}%` : values.level_50;

    return values;
};

const getRewardValueString = (reward) => {
    let valueString = "";

    if (!reward.min) return valueString;

    if (reward.min === reward.max) {
        if (reward.min > 0) valueString = `+${reward.min}`;
        else valueString = reward.min;
    } else {
        if (reward.min > 0) valueString = `+${reward.min}~${reward.max}`;
        else valueString = `${reward.min}~${reward.max}`;
    }

    return valueString;
};

const statNames = {
    journeyStartStats: "journey_start_stats",
    trainingEffects: "training_effects",
    telepathyEffects: "telepathy_effects",
    supportQuestEffects: "support_quest_effects",
};
const normalizeArcanas = (originData) => {
    const entities = {};
    const favorites = [];
    const ids = [];

    let arcanaFavorites = localStorage.getItem("arcana_favorites");
    if (!arcanaFavorites) {
        arcanaFavorites = [];
        localStorage.setItem("arcana_favorites", JSON.stringify(arcanaFavorites));
    } else {
        favorites.push(...JSON.parse(arcanaFavorites));
    }

    originData.forEach((arcana) => {
        ids.push(arcana.id);

        const parts = [];
        const eventParts = [];

        parts.push(arcana.name, arcana.char_name, arcana.main_stat, ...arcana.assists);

        const uniqueEffect = arcana.unique_effect
            ? {
                  name: arcana.unique_effect.name,
                  desc: arcana.unique_effect.desc,
              }
            : null;

        if (uniqueEffect) parts.push(uniqueEffect.name, uniqueEffect.desc);

        const stats = {
            journeyStartStats: [],
            trainingEffects: [],
            telepathyEffects: [],
            supportQuestEffects: [],
        };

        Object.keys(statNames).forEach((statName) => {
            const statList = arcana[statNames[statName]];

            statList.forEach((stat) => {
                const type = getTypeString(stat, arcana.main_stat);
                parts.push(type);

                stats[statName].push({
                    type: type,
                    ...getValuesSepLevel(stat),
                });
            });
        });

        const spPotential = potentials.find((e) => e.name === arcana.sp_potential);
        if (spPotential) parts.push(arcana.sp_potential);

        arcana.events.forEach((event) => {
            eventParts.push(event.name);

            event.choices.forEach((choice) => {
                [...choice.success_rewards, ...choice.failure_rewards].forEach((rewardRow) => {
                    rewardRow.forEach((reward) => {
                        let obj;

                        if (reward.type === "잠재력") obj = potentials.find((e) => e.id === reward.reward_id);
                        else if (reward.type === "여정 버프 획득") obj = buffs.find((e) => e.id === reward.reward_id);

                        const valueString = getRewardValueString(reward);

                        if (obj) {
                            eventParts.push(reward.type, obj.name, obj.desc);
                            reward.targetObj = obj;
                        } else {
                            eventParts.push(reward.type, valueString);
                        }

                        reward.valueString = valueString;
                    });
                });
            });
        });

        parts.push(...eventParts);

        entities[arcana.id] = {
            id: arcana.id,
            name: arcana.name,
            charName: arcana.char_name,
            rarity: arcana.rarity,
            mainStat: arcana.main_stat,
            assists: arcana.assists,
            spPotential: spPotential ?? null,
            uniqueEffect: uniqueEffect,
            stats: stats,
            events: arcana.events,
            searchText: parts.join(" "),
            eventSearchText: eventParts.join(" "),
        };
    });

    ids.sort((a, b) => {
        return (
            RARITY_BASIC_SCORE[entities[b].rarity] - RARITY_BASIC_SCORE[entities[a].rarity] ||
            STATUS_BASIC_SCORE[entities[a].mainStat] - STATUS_BASIC_SCORE[entities[b].mainStat] ||
            entities[a].name.localeCompare(entities[b].name, "ko-KR")
        );
    });

    return { ids, entities, favorites };
};

const normalized = normalizeArcanas(originData);

const arcanaSlice = createSlice({
    name: "arcanas",
    initialState: {
        ids: normalized.ids,
        entities: normalized.entities,
        favorites: normalized.favorites,
        filter: {
            rarity: FILTERS.ARCANA_RARITY[0],
            status: FILTERS.STATUS[0],
        },
    },
    reducers: {
        changeFilter: (state, action) => {
            state.filter[action.payload.id] = action.payload.obj;
        },
        toggleFavorite: (state, action) => {
            if (state.favorites.includes(action.payload)) {
                state.favorites = state.favorites.filter((e) => e !== action.payload);
            } else {
                state.favorites.push(action.payload);
            }
            localStorage.setItem("arcana_favorites", JSON.stringify(state.favorites));
        },
        reset: (state) => {
            state.value = origin;
        },
    },
});

export const { changeFilter, toggleFavorite } = arcanaSlice.actions;

export default arcanaSlice.reducer;
