import origin from "../data/saviors.json";

const getSaviorById = (id) => origin.find((e) => e.id === id);
const getSaviorByName = (name) => origin.find((e) => e.name === name);

const getSaviorByNameTitle = (string) => {
    const nameTitleRegex = new RegExp("(?<name>[가-힣 ]+)\\((?<title>[가-힣 ]+)\\)", "g");
    const result = nameTitleRegex.exec(string);
    
    if (result) {
        return origin.find((e) => e.name === result.groups?.name && e.title === result.groups?.title);
    } else {
        return result;
    }
};

export { getSaviorById, getSaviorByName, getSaviorByNameTitle };
