import React, { useState } from "react";
import styles from "./header.module.css";
import NavItem from "./nav-item/nav-item";
import { useDispatch, useSelector } from "react-redux";
import { toggle as toggleTheme } from "../../store/reducers/toggle/themeToggle";
import { toggle as toggleMode } from "../../store/reducers/toggle/modeToggle";

export default function Header({ title }) {
    const dispatch = useDispatch();

    const [isActive, setIsActive] = useState(false);

    const theme = useSelector((state) => state.theme.value);
    const mode = useSelector((state) => state.mode.value);

    let themeIcon = theme === "dark" ? "🌙" : "☀️";
    let modeIcon = mode === "pc" ? "🖥️" : "📱";
    localStorage.setItem("theme", theme);
    localStorage.setItem("mode", mode);

    const toggleNav = () => {
        setIsActive(!isActive);
    };

    return (
        <header id={styles["header-container"]}>
            <div className={styles["header"]}>
                <div className={styles["header-left"]}>
                    <div className={styles["hamburger-wrapper"]}>
                        <button className={styles["header-btn"]} title="메뉴" onClick={() => toggleNav()}>
                            <i className="fa-solid fa-bars" />
                        </button>
                        <div className={`${styles["nav-dropdown"]} ${isActive ? `${styles["active"]}` : ""}`}>
                            <NavItem to={"savior"} />
                            <NavItem to={"arcana"} />
                            <NavItem to={"deck"} />
                            <NavItem to={"journey"} />
                            <NavItem to={"schedule"} />
                            <NavItem to={"gacha"} />
                            <NavItem to={"item"} />
                        </div>
                    </div>
                </div>
                <div className={styles["title"]}>{title}</div>
                <div className={styles["header-right"]}>
                    <div className={styles["toggle-group"]}>
                        <button
                            className={styles["dark-light-toggle"]}
                            aria-hidden="true"
                            title="테마 변경"
                            onClick={() => dispatch(toggleTheme())}
                        >
                            <div className={`${styles["icon30"]} ${styles["sun"]}`}>
                                <svg xmlns="http://www.w3.org/2000/svg" height="24px" viewBox="0 -960 960 960" width="24px" fill="#222222">
                                    <path d="M480-280q-83 0-141.5-58.5T280-480q0-83 58.5-141.5T480-680q83 0 141.5 58.5T680-480q0 83-58.5 141.5T480-280ZM200-440H40v-80h160v80Zm720 0H760v-80h160v80ZM440-760v-160h80v160h-80Zm0 720v-160h80v160h-80ZM256-650l-101-97 57-59 96 100-52 56Zm492 496-97-101 53-55 101 97-57 59Zm-98-550 97-101 59 57-100 96-56-52ZM154-212l101-97 55 53-97 101-59-57Z" />
                                </svg>
                            </div>
                            <div className={`${styles["icon30"]} ${styles["moon"]}`}>
                                <svg xmlns="http://www.w3.org/2000/svg" height="24px" viewBox="0 -960 960 960" width="24px" fill="#FFFFFF">
                                    <path d="M480-120q-150 0-255-105T120-480q0-150 105-255t255-105q14 0 27.5 1t26.5 3q-41 29-65.5 75.5T444-660q0 90 63 153t153 63q55 0 101-24.5t75-65.5q2 13 3 26.5t1 27.5q0 150-105 255T480-120Z" />
                                </svg>
                            </div>
                        </button>
                    </div>
                </div>
            </div>
        </header>
    );
}
