import React, { useState } from "react";
import styles from "./skill.module.css";
import { SKILL_TYPE } from "../../../../constants";
import { v4 } from "uuid";
import { getSkillDescWithFlavorTexts, replaceColorTag } from "../../../../functions/stringFunctions";
import getImageFileName from "../../../../functions/getImageFileName";

export default function Skill({ charName, skill }) {
    const [isActive, setIsActive] = useState(false);

    const descObj = getSkillDescWithFlavorTexts(skill.levels.at(-1).skill_desc);

    return (
        <div className={styles["skill"]}>
            <div className={styles["skill-header"]}>
                <img src={`${process.env.PUBLIC_URL}/images/icon/skills/${charName}_${SKILL_TYPE[skill.type]}.webp`} />
                <div className={styles["skill-summary"]}>
                    <div className={styles["name-wrapper"]}>
                        <span className={styles["skill-name"]}>{skill.name}</span>
                        <span className={styles["skill-type"]}>{SKILL_TYPE[skill.type]}</span>
                    </div>
                    {((skill.cooltime || skill.target || skill.break || skill.nova) && (
                        <div className={styles["badges"]}>
                            {skill.cooltime !== 0 && <span className={`${styles["badge"]} ${styles["cooltime"]}`}>{skill.cooltime}턴</span>}
                            {skill.target && skill.target.includes("적") && (
                                <span className={`${styles["badge"]} ${styles["target"]}`}>{skill.target}</span>
                            )}
                            {skill.target && (skill.target.includes("아군") || skill.target.includes("자신")) && (
                                <span className={`${styles["badge"]} ${styles["target-ally"]}`}>{skill.target}</span>
                            )}
                            {skill.break !== 0 && (
                                <span className={`${styles["badge"]} ${styles["break"]}`}>강인도 피해 {skill.break}</span>
                            )}
                            {skill.nova !== 0 && (
                                <span className={`${styles["badge"]} ${styles["nova-gain"]}`}>노바 획득 {skill.nova}</span>
                            )}
                        </div>
                    )) || (
                        <div className={styles["badges"]}>
                            <span className={`${styles["badge"]} ${styles["blank"]}`}> </span>
                        </div>
                    )}
                </div>
            </div>
            <div className={styles["skill-desc-wrapper"]}>
                <div className={styles["skill-desc"]} dangerouslySetInnerHTML={{ __html: descObj.desc }}></div>
                {descObj.buffList.length > 0 && (
                    <div className={styles["flavor-texts"]}>
                        {descObj.buffList.map((buff) => {
                            return (
                                <div key={v4()}>
                                    <img src={`${process.env.PUBLIC_URL}/images/icon/buff/${getImageFileName(buff.name)}.webp`} />
                                    &nbsp;
                                    <span className={styles["buff-name"]}>{buff.name}</span>&nbsp;:&nbsp;<span>{buff.desc}</span>
                                </div>
                            );
                        })}
                    </div>
                )}
            </div>
            {skill.type !== 0 && (
                <div className={styles["skill-nova"]}>
                    <span className={`${styles["badge"]} ${styles["nova"]}`}>노바 버스트</span>
                    <span className={styles["desc"]} dangerouslySetInnerHTML={{ __html: replaceColorTag(skill.nova_desc) }}></span>
                </div>
            )}
            <div className={`${styles["level-data-wrapper"]} ${isActive ? `${styles["active"]}` : ""} `}>
                <button className={styles["show-level-button"]} onClick={() => setIsActive(!isActive)}>
                    스킬 레벨 정보 <span className={styles["triangle"]}>▼</span>
                </button>
                <div className={styles["level-data"]}>
                    {skill.levels.map((level_info) => {
                        if (skill.type === 0) {
                            // passive
                            return (
                                <div className={styles["row"]} key={v4()}>
                                    <span className={styles["level"]}>{level_info.level}</span>
                                    <span
                                        className={styles["value"]}
                                        dangerouslySetInnerHTML={{ __html: replaceColorTag(level_info.skill_desc) }}
                                    ></span>
                                </div>
                            );
                        } else {
                            // active
                            return (
                                <div className={styles["row"]} key={v4()}>
                                    <span className={styles["level"]}>{level_info.level}</span>
                                    <span className={styles["value"]}>{level_info.level_desc}</span>
                                </div>
                            );
                        }
                    })}
                </div>
            </div>
        </div>
    );
}
