import React, { useState } from "react";
import styles from "./standard-reward-row.module.css";
import { v4 } from "uuid";
import getImageFileName from "../../../../functions/getImageFileName";

export default function StandardRewardRow({ reward }) {
    const [isActive, setIsActive] = useState(false);

    const getSignMarkedValue = (value) => {
        if (value > 0) return `+${value}`;

        return value;
    };

    const innerHTML = reward.map((each, index) => {
        if (each.type === "스탯") {
            return (
                <div className={styles["desc-row"]} key={v4()}>
                    {each.reward_stat}
                    &nbsp;
                    <span className={styles["plus"]}>
                        {each.min === each.max
                            ? getSignMarkedValue(each.min)
                            : `${getSignMarkedValue(each.min)}~${getSignMarkedValue(each.max)}`}
                    </span>
                    {index < reward.length - 1 && <span className={styles["plain"]}>&nbsp;&nbsp;or&nbsp;&nbsp;</span>}
                </div>
            );
        } else if (each.type === "잠재력") {
            return (
                <div className={`${styles["desc-row"]} ${styles["special"]}`} onClick={() => setIsActive(!isActive)} key={v4()}>
                    {each.type}
                    &nbsp;
                    <div className={styles["potential-icon"]}>
                        {each.targetObj.unitId === 0 && each.targetObj.class === "" && (
                            <img src={`${process.env.PUBLIC_URL}/images/icon/potential/bg_yellow.webp`} />
                        )}
                        {each.targetObj.unitId !== 0 && each.targetObj.class !== "" && (
                            <img src={`${process.env.PUBLIC_URL}/images/icon/potential/bg_blue.webp`} />
                        )}
                        <img
                            src={`${process.env.PUBLIC_URL}/images/icon/potential/${getImageFileName(each.targetObj.name)}.webp`}
                            className={styles["potential-logo"]}
                        />
                    </div>
                    &nbsp;
                    {each.targetObj.name}
                    &nbsp;
                    {/* <span className={styles["plus"]}>+1</span> */}
                    {index < reward.length - 1 && <span className={styles["plain"]}>&nbsp;&nbsp;or&nbsp;&nbsp;</span>}
                </div>
            );
        } else if (each.type === "여정 버프 획득") {
            return (
                <div className={`${styles["desc-row"]} ${styles["special"]}`} onClick={() => setIsActive(!isActive)} key={v4()}>
                    {each.type}
                    &nbsp;
                    <img src={`${process.env.PUBLIC_URL}/images/icon/journey_buff/${getImageFileName(each.targetObj.name)}.webp`} />
                    &nbsp;{each.targetObj.name}
                    &nbsp;
                    <span className={styles["plus"]}>
                        {each.min === each.max
                            ? getSignMarkedValue(each.min)
                            : `${getSignMarkedValue(each.min)}~${getSignMarkedValue(each.max)}`}
                    </span>
                    {index < reward.length - 1 && <span className={styles["plain"]}>&nbsp;&nbsp;or&nbsp;&nbsp;</span>}
                </div>
            );
        } else {
            return (
                <div className={styles["desc-row"]} key={v4()}>
                    {each.type}
                    &nbsp;
                    <span className={styles["plus"]}>
                        {each.min === each.max
                            ? getSignMarkedValue(each.min)
                            : `${getSignMarkedValue(each.min)}~${getSignMarkedValue(each.max)}`}
                    </span>
                    {index < reward.length - 1 && <span className={styles["plain"]}>&nbsp;&nbsp;or&nbsp;&nbsp;</span>}
                </div>
            );
        }
    });

    return (
        <div className={styles["reward"]} style={{ maxHeight: `${isActive ? 100 : 17}px` }}>
            <div className={styles["desc"]}>{innerHTML}</div>
            {reward[0].type === "잠재력" && <div className={styles["value-desc"]}>{reward[0].targetObj.desc}</div>}
            {reward[0].type === "여정 버프 획득" && (
                <div className={styles["value-desc"]}>
                    <div className={styles["value-desc"]}>{reward[0].targetObj.desc}</div>
                </div>
            )}
        </div>
    );
}
