import React from "react";
import styles from "./portrait-with-name.module.css";

export default function PortraitWithName({ savior, setIsActive, setSelected }) {
    let eng = "";
    switch (savior.attr) {
        case "태양":
            eng = "sun";
            break;
        case "달":
            eng = "moon";
            break;
        case "별":
            eng = "star";
            break;
        case "질서":
            eng = "order";
            break;
        case "혼돈":
            eng = "chaos";
            break;
    }

    const selectSavior = (savior) => {
        setSelected(savior);
        setIsActive(true);
    };

    return (
        <div className={styles["savior"]} onClick={() => selectSavior(savior)}>
            <div className={`${styles["portrait"]} ${styles[`${eng}`]}`}>
                <img alt={savior.name} src={`${process.env.PUBLIC_URL}/images/icon/portrait/${savior.name}(${savior.title}).webp`} />
                <div className={styles["class-overlay"]}>
                    <img src={`${process.env.PUBLIC_URL}/images/icon/portrait/${savior.attr}.webp`} className={styles["attr"]} />
                    <img src={`${process.env.PUBLIC_URL}/images/icon/portrait/${savior.class}.webp`} className={styles["class"]} />
                </div>
            </div>
            <div className={styles["name-wrapper"]}>
                <div className={styles["name"]}>{savior.name}</div>
                <div className={styles["title"]}>{savior.title.trim()}</div>
            </div>
        </div>
    );
}
