import React, { useState } from "react";
import styles from "./filter-select.module.css";
import { useDispatch, useSelector } from "react-redux";
import { v4 } from "uuid";

export default function FilterSelect({ id, list, selected, changeFilter, showName = true, isUseDispatch = true, forceWidth = undefined }) {
    const [isActive, setIsActive] = useState(false);

    const dispatch = useDispatch();

    let name = "";
    if (id === "rarity") name = "등급";
    if (id === "attr") name = "속성";
    if (id === "class") name = "클래스";
    if (id === "status") name = "메인 스탯";
    if (id === "weather") name = "날씨 이벤트를 선택하세요";
    if (id === "arcana") name = "아르카나를 선택하세요";
    if (id === "item_type") name = "종류";
    if (id === "item_sort") name = "기본 정렬";
    if (id === "journey_difficulty") name = "난이도";

    const dispatchFilter = (obj) => {
        if (isUseDispatch) {
            if (typeof obj === "string") {
                dispatch(changeFilter(obj));
            } else {
                dispatch(changeFilter({ id, obj }));
            }
        } else {
            changeFilter(obj);
        }
    };

    const width = forceWidth ? { minWidth: `${forceWidth}px` } : {};

    return (
        <div className={styles["select-wrapper"]} style={width} onClick={() => setIsActive(!isActive)}>
            <div className={`${styles["title"]} ${showName && selected.value === "all" ? "" : `${styles["disabled"]}`}`}>{name}</div>
            {/* <div className={`${styles["title"]} ${!showName || selected.value !== "all" ? `${styles["disabled"]}` : ""}`}>:</div> */}

            {typeof selected === "object" && selected.value !== "all" && <div className={styles["represent"]}>{selected.name}</div>}
            {typeof selected === "string" && (
                <div className={styles["represent"]}>{list.find((item) => item.value === selected)?.name || selected}</div>
            )}

            <div className={`${styles["list"]} ${isActive ? `${styles["active"]}` : ""}`}>
                {list.map((element) => {
                    return (
                        <div className={styles["element"]} onClick={() => dispatchFilter(element)} key={`${v4()}`}>
                            {element.name || element}
                        </div>
                    );
                })}
            </div>
        </div>
    );
}
