import React from "react";
import styles from "./checkbox.module.css";

export default function Checkbox({ value, setValue, text }) {
    return (
        <div className={styles["checker"]} onClick={() => setValue()}>
            <i className={`fa-regular ${value === true ? "fa-square-check" : "fa-square"}`} />
            <span>{text}</span>
        </div>
    );
}