import React, { useState } from "react";
import styles from "./arcana-desc-modal.module.css";
import ModalRight from "./modal-right/modal-right";
import getImageFileName from "../../../functions/getImageFileName";

const levelFlags = ["level_35", "level_50"];

export default function ArcanaDescModal({ isActive, setIsActive, selected }) {
    const [levelFlag, setLevelFlag] = useState(localStorage.getItem("level_flag") || "level_50");

    const changeLevelFlag = (flag) => {
        if (!levelFlags.includes(flag)) return;

        localStorage.setItem("level_flag", flag);
        setLevelFlag(flag);
    };

    return (
        <div
            className={`modal ${isActive ? "active" : ""}`}
            onClick={(e) => {
                if (e.target.classList.contains("modal")) {
                    setIsActive(false);
                }
            }}
        >
            <div className="window">
                <button className="close-button" onClick={() => setIsActive(false)}>
                    <i className="fa-solid fa-x" />
                </button>
                <div className="level-buttons">
                    <button
                        type="button"
                        className={`${levelFlag === levelFlags[0] ? "active" : ""}`}
                        onClick={() => changeLevelFlag(levelFlags[0])}
                    >
                        Lv.35
                    </button>
                    <button
                        type="button"
                        className={`${levelFlag === levelFlags[1] ? "active" : ""}`}
                        onClick={() => changeLevelFlag(levelFlags[1])}
                    >
                        Lv.50
                    </button>
                </div>

                {selected && (
                    <div className={styles["illustration"]}>
                        <img src={`${process.env.PUBLIC_URL}/images/cards/${getImageFileName(selected.name)}.webp`} />
                    </div>
                )}

                {selected && <ModalRight selected={selected} levelFlag={levelFlag} />}
            </div>
        </div>
    );
}
