import React, { useState } from "react";
import styles from "./hurdle.module.css";
import { v4 } from "uuid";
import DescriptionWrapper from "./description-wrapper";

export default function Hurdle({ schedules, setSelected }) {
    const [isFold, setIsFold] = useState(false);

    return (
        <div className={`${styles["hurdle"]} ${isFold ? "" : `${styles["active"]}`}`}>
            <button type="button" className={styles["hurdle-title"]} onClick={() => setIsFold(!isFold)}>
                {schedules[0].title}
                <span className={styles["triangle"]}>▼</span>
            </button>
            <div className={styles["turns"]}>
                {schedules.map((turn) => {
                    return (
                        <div className={styles["turn"]} key={v4()}>
                            <div className={styles["turn-info"]}>
                                <div className={styles["title"]}>
                                    <span className={styles["turn-count"]}>{turn.turn}턴</span>
                                    <span className={styles["turn-time"]}>{turn.time}</span>
                                </div>
                                <div className={styles["turn-description"]}>
                                    {turn.befores.length > 0 && <div className={styles["description-title"]}>행동 전</div>}
                                    {turn.befores.length > 0 &&
                                        turn.befores.map((before, index) => {
                                            return <DescriptionWrapper desc={before} setSelected={setSelected} key={v4()} />;
                                        })}
                                    {turn.currents.length > 0 && <div className={styles["description-title"]}>행동</div>}
                                    {turn.currents.length > 0 &&
                                        turn.currents.map((current, index) => {
                                            return <DescriptionWrapper desc={current} setSelected={setSelected} key={v4()} />;
                                        })}
                                    {turn.afters.length > 0 && <div className={styles["description-title"]}>행동 후</div>}
                                    {turn.afters.length > 0 &&
                                        turn.afters.map((after, index) => {
                                            return <DescriptionWrapper desc={after} setSelected={setSelected} key={v4()} />;
                                        })}
                                </div>
                            </div>
                        </div>
                    );
                })}
            </div>
        </div>
    );
}
