import { createSlice } from "@reduxjs/toolkit";
import originData from "../../../data/journey_items.json";
import FILTERS from "../../../data/filter_config.json";
import SORT_LIST from "../../../data/sort_config.json";
import { replaceColorTag } from "../../../functions/stringFunctions";

const rarity_score = {
    전설: 0,
    유니크: 1,
    레어: 2,
};

const type_score = {
    부적: 0,
    음식: 1,
    "훈련 서적": 2,
    귀중품: 3,
};

const normalizeItems = (originData) => {
    const ids = [];
    const entities = {};

    originData.forEach((data) => {
        ids.push(data.id);

        const parts = [data.name, data.description];

        if (data.charm_info) {
            data.charm_info.se_list.forEach((se) => {
                const cleanedSe = replaceColorTag(se);
                parts.push(cleanedSe);
            });
        }

        if (data.stats) {
            parts.push(...data.stats.map((stat) => `${stat.type} ${stat.value < 0 ? stat.value : `+${stat.value}`}`));
        }

        if (data.events) parts.push(...data.events);
        if (data.regions) parts.push(...data.regions);

        entities[data.id] = {
            ...data,
            typeEng: FILTERS.ITEM_TYPE.find((e) => e.name === data.type).value,
            rarityEng: FILTERS.ITEM_RARITY.find((e) => e.name === data.rarity).value,
            searchText: parts.join(" "),
        };
    });

    ids.sort((a, b) => {
        const typeDiff = type_score[entities[a].type] - type_score[entities[b].type];
        if (typeDiff !== 0) return typeDiff;

        const rarityDiff = rarity_score[entities[a].rarity] - rarity_score[entities[b].rarity];
        if (rarityDiff !== 0) return rarityDiff;

        return entities[a].name.localeCompare(entities[b].name, "ko-KR");
    });

    return { ids, entities };
};

const normalized = normalizeItems(originData);

const itemSlice = createSlice({
    name: "items",
    initialState: {
        ids: normalized.ids,
        entities: normalized.entities,
        filter: {
            type: FILTERS.ITEM_TYPE[0],
            sort: SORT_LIST.ITEM_SORT[0],
        },
    },
    reducers: {
        setSortFilter: (state, action) => {
            state.filter.sort = action.payload.obj;
        },
        setTypeFilter: (state, action) => {
            state.filter.type = action.payload.obj;
        },
    },
});

export const { setSortFilter, setTypeFilter } = itemSlice.actions;

export default itemSlice.reducer;
