import React from "react";
import styles from "./stat.module.css";

export default function Stat({ obj, levelFlag, isThin, mainStat }) {
    return (
        <div className={`${styles["stat"]} ${isThin ? `${styles["thin"]}` : ""}`}>
            {obj.type === "{stat}" ? mainStat : obj.type}
            &nbsp;<span>+{obj[`${levelFlag}_string`]}</span>
        </div>
    );
}
